DROP TABLE IF EXISTS `recepciones`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `recepciones` (
  `recepcion_id` int NOT NULL AUTO_INCREMENT,
  `oficina_id` int NOT NULL,
  `producto_id` int NOT NULL,
  `fecha_recepcion` date NOT NULL,
  `lote` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `estado_recepcion` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'ACTIVO',
  `dias_inactivo` int DEFAULT NULL,
  `ingresado_sin_venta` tinyint(1) NOT NULL DEFAULT '1',
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`recepcion_id`),
  KEY `fk_rec_producto` (`producto_id`),
  KEY `idx_rec_fecha` (`fecha_recepcion`),
  KEY `idx_rec_estado` (`estado_recepcion`),
  KEY `idx_rec_oficina` (`oficina_id`),
  CONSTRAINT `fk_rec_oficina` FOREIGN KEY (`oficina_id`) REFERENCES `oficinas` (`oficina_id`),
  CONSTRAINT `fk_rec_producto` FOREIGN KEY (`producto_id`) REFERENCES `productos` (`producto_id`)
) ENGINE=InnoDB AUTO_INCREMENT=1666 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

